// System prompt assembly, intent matchers and temp-prompt handling.
//
// Port of agent/prompts.py (the behavioural spec; parity-tested against output generated by the
// real Python via scripts/golden/export_prompts.py -> test/golden/prompts.json).
//
// The static blocks live in ./prompt-text/ and are byte-identical to the Python strings.
// They are regenerated by that script, not hand-edited, and loaded with Bun text imports (these
// are embedded by `bun build --compile`).
import analyzeGuide from './prompt-text/analyze-guide.txt' with { type: 'text' }
import browserRules from './prompt-text/browser-rules.txt' with { type: 'text' }
import chartIds from './prompt-text/chart-ids.txt' with { type: 'text' }
import chartRules from './prompt-text/chart-rules.txt' with { type: 'text' }
import commandHints from './prompt-text/command-hints.json' with { type: 'json' }
import coreRules from './prompt-text/core-rules.txt' with { type: 'text' }
import dataRules from './prompt-text/data-rules.txt' with { type: 'text' }
import diagramRules from './prompt-text/diagram-rules.txt' with { type: 'text' }
import hooksRules from './prompt-text/hooks-rules.txt' with { type: 'text' }
import ingestRules from './prompt-text/ingest-rules.txt' with { type: 'text' }
import knowledgeRules from './prompt-text/knowledge-rules.txt' with { type: 'text' }
import multiSourceRules from './prompt-text/multi-source-rules.txt' with { type: 'text' }
import outputRules from './prompt-text/output-rules.txt' with { type: 'text' }
import skillCatalogRules from './prompt-text/skill-catalog-rules.txt' with { type: 'text' }
import teamsRules from './prompt-text/teams-rules.txt' with { type: 'text' }
import unnamedColumnRules from './prompt-text/unnamed-column-rules.txt' with { type: 'text' }
import workspaceRules from './prompt-text/workspace-rules.txt' with { type: 'text' }
import { say } from '../i18n.ts'

// ── Static blocks ───────────────────────────────────────────────────────────

export const CORE_RULES: string = coreRules
export const DATA_RULES: string = dataRules
export const WORKSPACE_RULES: string = workspaceRules
export const KNOWLEDGE_RULES: string = knowledgeRules
export const CHART_RULES: string = chartRules
export const OUTPUT_RULES: string = outputRules
export const TEAMS_RULES: string = teamsRules
export const HOOKS_RULES: string = hooksRules
export const BROWSER_RULES: string = browserRules
export const INGEST_RULES: string = ingestRules
export const MULTI_SOURCE_RULES: string = multiSourceRules
export const UNNAMED_COLUMN_RULES: string = unnamedColumnRules
export const DIAGRAM_RULES: string = diagramRules
/** Template with a single `{catalog}` placeholder (Python `str.format(catalog=...)`). */
export const SKILL_CATALOG_RULES: string = skillCatalogRules

/**
 * Python `prompts._ANALYZE_GUIDE` = `Function.Analyze.registry.build_agent_desc()`, evaluated at
 * import time. Frozen snapshot: it is derived from the analyze registry, which moves with the
 * compute port; the tool-schema code that consumes it should regenerate it from the new registry.
 */
export const ANALYZE_GUIDE: string = analyzeGuide

/**
 * Python `prompts._CHART_IDS` = `", ".join(c["chart_id"] for c in LLM.chart_selector._CHARTS)`.
 * Frozen snapshot; derived from the chart selector registry, which moves with the compute port.
 */
export const CHART_IDS: string = chartIds

/** Slash-command -> system hint (Python `COMMAND_HINTS`, same key order). */
export const COMMAND_HINTS: Readonly<Record<string, string>> = commandHints

// ── Python-compatible text primitives ───────────────────────────────────────

// Python's `str.isspace()` set (what `str.strip()` and the unicode `\s` use). JS differs: it
// also treats U+FEFF as whitespace and lacks U+001C-U+001F and U+0085.
const PY_SPACE = '\\t\\n\\v\\f\\r\\x1c-\\x20\\x85\\xa0\\u1680\\u2000-\\u200a\\u2028\\u2029\\u202f\\u205f\\u3000'
const PY_SPACE_CHAR = new RegExp(`[${PY_SPACE}]`, 'u')
// Python's unicode `\w` (str.isalnum() or "_").
const PY_WORD = '\\p{L}\\p{N}_'

/**
 * Translate a Python `re` source (restricted to the constructs used in agent/prompts.py) to a JS
 * RegExp with Python semantics:
 *  - `\s`/`\S` use Python's whitespace set; `\d` is any decimal digit (`\p{Nd}`);
 *  - `\b` uses Python's unicode word chars (JS `\b` is ASCII-only);
 *  - `.` matches everything except `\n` (JS also excludes `\r`, U+2028, U+2029);
 *  - IGNORECASE additionally lets ASCII `i` match U+0130/U+0131, as Python does (JS /iu does not).
 * Case folding of K (Kelvin) and s (long s) is already handled by the `iu` flags.
 */
function pyRegex(source: string, ignoreCase: boolean): RegExp {
  let out = ''
  let inClass = false
  for (let i = 0; i < source.length; i++) {
    const ch = source[i]!
    if (ch === '\\') {
      const next = source[++i]!
      if (next === 's') out += inClass ? PY_SPACE : `[${PY_SPACE}]`
      else if (next === 'S') {
        if (inClass) throw new Error(`unsupported \\S inside a character class: ${source}`)
        out += `[^${PY_SPACE}]`
      } else if (next === 'd') out += '\\p{Nd}'
      else if (next === 'b') out += `(?:(?<=[${PY_WORD}])(?![${PY_WORD}])|(?<![${PY_WORD}])(?=[${PY_WORD}]))`
      else out += ch + next
    } else if (inClass) {
      if (ch === ']') inClass = false
      out += ch
    } else if (ch === '[') {
      inClass = true
      out += ch
      if (source[i + 1] === '^') out += source[++i]!
    } else if (ch === '.') out += '[^\\n]'
    else if (ignoreCase && (ch === 'i' || ch === 'I')) out += '[iI\\u0130\\u0131]'
    else out += ch
  }
  return new RegExp(out, ignoreCase ? 'iu' : 'u')
}

/** Python `str.strip()` (no args). */
function pyStrip(text: string): string {
  let start = 0
  let end = text.length
  while (start < end && PY_SPACE_CHAR.test(text[start]!)) start++
  while (end > start && PY_SPACE_CHAR.test(text[end - 1]!)) end--
  return text.slice(start, end)
}

// ── Intent matchers ─────────────────────────────────────────────────────────

const WORKSPACE_INTENT_RE = pyRegex(
  String.raw`(workspace|workdir|local\s+file|folder|directory|on\s+disk|` +
    String.raw`工作目录|工作区|本地文件|目录|文件夹|磁盘|读取文件|打开文件|查找文件)`,
  true,
)
const WORKSPACE_FILE_EXT_RE = pyRegex(String.raw`\.(?:csv|xlsx?|xlsm|docx?|txt|md|pdf)\b`, true)
const HOOKS_INTENT_RE = pyRegex(
  String.raw`(hooks?|webhooks?|callback|automation|回调|自动化|钩子|配置这个.{0,20}(?:链接|url))`,
  true,
)
const BROWSER_INTENT_RE = pyRegex(String.raw`(google|baidu|bing|search|搜索|调研|查找|查一下|浏览器|browser)`, true)
const INGEST_URL_RE = pyRegex(String.raw`https?://\S+`, true)
const INGEST_HINT_RE = pyRegex(
  String.raw`(表格|数据|抓取|抓下来|爬取|提取|导入|转成.{0,6}表|scrape|crawl|fetch|import|` +
    String.raw`table|dataset|csv|json|pdf)`,
  true,
)
const CHART_INTENT_RE = pyRegex(String.raw`(chart|plot|visuali[sz]|dashboard|图表|可视化|画图|绘图|看板)`, true)
const NON_BUSINESS_KNOWLEDGE_RE = pyRegex(
  String.raw`^\s*(?:你是谁|你叫什么|介绍(?:一下)?你自己|who\s+are\s+you|what(?:'s| is)\s+your\s+name|` +
    String.raw`你好|您好|hello|hi|谢谢|thanks?|help|帮助)\s*[？?!！。.]*\s*$`,
  true,
)
const BUSINESS_ANALYSIS_RE = pyRegex(
  String.raw`(分析|统计|查询|计算|汇总|总结|对比|比较|趋势|变化|增长|下降|占比|分布|排名|预测|回归|` +
    String.raw`相关性|异常|诊断|洞察|指标|口径|规则|成本|收入|利润|订单|客户|用户|销售|` +
    String.raw`运营|转化|留存|流失|效率|绩效|预算|业务|报表|数据|schema|sql|metric|kpi|` +
    String.raw`analy[sz]|trend|forecast|revenue|profit|cost|sales|customer|retention|churn)`,
  true,
)
const FILE_NAVIGATION_RE = pyRegex(
  String.raw`(打开|读取|查找|列出|浏览|上传|删除|移动|重命名|open|read|find|list|browse|upload|delete|move|rename)` +
    String.raw`.{0,20}(文件|目录|文件夹|file|folder|directory)`,
  true,
)
const ANALYSIS_ACTION_RE = pyRegex(
  String.raw`(分析|统计|查询|计算|汇总|总结|对比|比较|趋势|变化|增长|下降|占比|分布|排名|预测|` +
    String.raw`回归|相关性|异常|诊断|洞察|analy[sz]|trend|forecast|compare|calculate)`,
  true,
)
// Case-sensitive in Python (no IGNORECASE).
const UNNAMED_COLUMN_RE = pyRegex(String.raw`(?<![A-Za-z0-9_])col(?:_\d+)?(?![A-Za-z0-9_])`, false)

export function messageNeedsWorkspaceRules(message: string | null | undefined, opts: { hasWorkspace?: boolean } = {}): boolean {
  const text = message ?? ''
  return WORKSPACE_INTENT_RE.test(text) || (opts.hasWorkspace === true && WORKSPACE_FILE_EXT_RE.test(text))
}

export function messageNeedsHooksRules(message: string | null | undefined): boolean {
  return HOOKS_INTENT_RE.test(message ?? '')
}

export function messageNeedsBrowserRules(message: string | null | undefined): boolean {
  return BROWSER_INTENT_RE.test(message ?? '')
}

/** A bare URL alone must not attach the block; an ingest hint is required too. */
export function messageNeedsIngestRules(message: string | null | undefined): boolean {
  const text = message ?? ''
  return INGEST_URL_RE.test(text) && INGEST_HINT_RE.test(text)
}

export function messageNeedsChartRules(message: string | null | undefined): boolean {
  return CHART_INTENT_RE.test(message ?? '')
}

/** Diagram rules attach only when the canvas skill is explicitly activated (message is ignored). */
export function messageNeedsDiagramRules(_message: string | null | undefined, opts: { hasCanvasSkill?: boolean } = {}): boolean {
  return opts.hasCanvasSkill ?? false
}

/** Conservative privacy gate for knowledge retrieval. */
export function messageNeedsKnowledge(message: string | null | undefined): boolean {
  const text = pyStrip(message ?? '')
  if (!text || NON_BUSINESS_KNOWLEDGE_RE.test(text)) return false
  if (FILE_NAVIGATION_RE.test(text) && !ANALYSIS_ACTION_RE.test(text)) return false
  return BUSINESS_ANALYSIS_RE.test(text)
}

export function schemaHasUnnamedColumns(schema: string | null | undefined): boolean {
  return UNNAMED_COLUMN_RE.test(schema ?? '')
}

// ── System prompt ───────────────────────────────────────────────────────────

/** Deterministic capability context used to assemble the system prompt. */
export interface PromptContext {
  readonly hasDataSource: boolean
  readonly sourceCount: number
  readonly hasWorkspace: boolean
  readonly needsWorkspace: boolean
  readonly teamsEnabled: boolean
  readonly activationKind: string
  readonly activationName: string
  readonly needsChart: boolean
  readonly needsOutput: boolean
  readonly needsHooks: boolean
  readonly needsBrowser: boolean
  readonly needsIngest: boolean
  readonly hasKnowledge: boolean
  readonly hasUnnamedColumns: boolean
  readonly needsDiagram: boolean
  readonly skillCatalog: string
}

const DEFAULT_PROMPT_CONTEXT: PromptContext = {
  hasDataSource: false,
  sourceCount: 0,
  hasWorkspace: false,
  needsWorkspace: false,
  teamsEnabled: false,
  activationKind: '',
  activationName: '',
  needsChart: false,
  needsOutput: false,
  needsHooks: false,
  needsBrowser: false,
  needsIngest: false,
  hasKnowledge: false,
  hasUnnamedColumns: false,
  needsDiagram: false,
  skillCatalog: '',
}

/**
 * Assemble stable prompt blocks in a fixed order for prompt-cache reuse. Omitted context fields
 * take the Python dataclass defaults. (The Python `knowledge_summary` compatibility argument was
 * always ignored and is dropped.)
 */
export function getSystemPrompt(context: Partial<PromptContext> | null = null): string {
  const ctx = { ...DEFAULT_PROMPT_CONTEXT, ...context }
  const blocks = [CORE_RULES]
  if (ctx.hasDataSource) blocks.push(DATA_RULES)
  if (ctx.needsWorkspace) blocks.push(WORKSPACE_RULES)
  if (ctx.hasKnowledge) blocks.push(KNOWLEDGE_RULES)
  if (ctx.needsChart) blocks.push(CHART_RULES)
  if (ctx.needsOutput) blocks.push(OUTPUT_RULES)
  if (ctx.teamsEnabled) blocks.push(TEAMS_RULES)
  if (ctx.needsHooks) blocks.push(HOOKS_RULES)
  if (ctx.needsBrowser) blocks.push(BROWSER_RULES)
  if (ctx.needsIngest) blocks.push(INGEST_RULES)
  if (ctx.sourceCount > 1) blocks.push(MULTI_SOURCE_RULES)
  if (ctx.hasUnnamedColumns) blocks.push(UNNAMED_COLUMN_RULES)
  if (ctx.needsDiagram) blocks.push(DIAGRAM_RULES)
  // Replacer function: the catalog is inserted verbatim (no `$&`-style expansion).
  if (ctx.skillCatalog) blocks.push(SKILL_CATALOG_RULES.replace('{catalog}', () => ctx.skillCatalog))
  return blocks
    .map(pyStrip)
    .filter((block) => block !== '')
    .join('\n\n')
}

// ── Temporary per-session prompt ────────────────────────────────────────────

/** Hard cap on the injected temp-prompt length (code points). ~4000 chars ≈ 1100 tokens. */
export const TEMP_PROMPT_MAX_CHARS = 4000

// Python spells "any char" as `[\s\S]`; `[^]` is the same set.
const THINK_BLOCK_RE = pyRegex(String.raw`<think\b[^>]*>[^]*?</think\s*>`, true)
const THINK_OPEN_RE = pyRegex(String.raw`<think\b[^>]*>`, true)
const THINK_CLOSE_RE = pyRegex(String.raw`</think\s*>`, true)
const THINK_BLOCK_GLOBAL_RE = new RegExp(THINK_BLOCK_RE.source, 'giu')
const THINK_CLOSE_GLOBAL_RE = new RegExp(THINK_CLOSE_RE.source, 'giu')

/** Remove reasoning blocks accidentally emitted by thinking models. */
export function stripTempPromptThinking(tempPrompt: string | null | undefined): string {
  let text = pyStrip(tempPrompt ?? '')
  if (!text) return ''

  // Most OpenAI-compatible reasoning models wrap hidden reasoning this way.
  text = text.replace(THINK_BLOCK_GLOBAL_RE, '')

  // An opening tag that is never closed: everything after it is reasoning, not an instruction.
  const unclosed = THINK_OPEN_RE.exec(text)
  if (unclosed) text = text.slice(0, unclosed.index)

  // Orphan closing tags left by malformed provider output.
  text = text.replace(THINK_CLOSE_GLOBAL_RE, '')
  return pyStrip(text.replace(/\n{3,}/g, '\n\n'))
}

/**
 * Wrap a user's per-session temporary instruction for system-prompt injection. Empty string when
 * there is nothing to inject. The temp instruction overrides ordinary default behaviour but must
 * never override the ABSOLUTE no-fabrication rule or the output-format rules in the system prompt.
 */
export function buildTempPromptSection(tempPrompt: string | null | undefined): string {
  let text = stripTempPromptThinking(tempPrompt)
  if (!text) return ''
  // Python len()/slicing count code points, not UTF-16 units.
  const codePoints = Array.from(text)
  if (codePoints.length > TEMP_PROMPT_MAX_CHARS) {
    text = codePoints.slice(0, TEMP_PROMPT_MAX_CHARS).join('') + say('\n…[temporary instruction truncated]', '\n…[临时指令已截断]')
  }
  return (
    say(
      '\n\n## Temporary instruction for this session (set by the user for the current conversation)\n' +
        'The following instruction was set temporarily by the user for this conversation and takes priority over ordinary default behavior; ' +
        'but it must never violate the "ABSOLUTE RULE — NO FABRICATION" above or the output format rules.\n',
      '\n\n## 本次会话临时指令（用户为当前对话设定）\n' +
        '以下指令由用户为这次对话临时设定，优先级高于一般默认行为；' +
        '但绝对不可违反上文的「ABSOLUTE RULE — NO FABRICATION」与输出格式规则。\n',
    ) +
    text
  )
}
